def transform(grid):
    h, w = len(grid), len(grid[0])
    background = grid[0][0]
    exterior = set()
    queue = deque()
    for r in range(h):
        for c in (0, w - 1):
            if grid[r][c] == background and (r, c) not in exterior:
                exterior.add((r, c)); queue.append((r, c))
    for c in range(w):
        for r in (0, h - 1):
            if grid[r][c] == background and (r, c) not in exterior:
                exterior.add((r, c)); queue.append((r, c))
    while queue:
        r, c = queue.popleft()
        for nr, nc in ((r-1,c), (r+1,c), (r,c-1), (r,c+1)):
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == background and (nr,nc) not in exterior:
                exterior.add((nr,nc)); queue.append((nr,nc))
    holes = {(r,c) for r in range(h) for c in range(w)
             if grid[r][c] == background and (r,c) not in exterior}
    out = [row[:] for row in grid]
    for r, c in holes:
        out[r][c] = 4
    # A line crossing the interior may split one cavity into aligned sections.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != background and (
                ((r-1,c) in holes and (r+1,c) in holes) or
                ((r,c-1) in holes and (r,c+1) in holes)):
